6	    expect(quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [])).toBe(5);
7	  });
8	  it("should charge 100G base premium plus fee for a single sword", () => {
9	    expect(
10	      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [{ type: "sword" }]),
11	    ).toBe(105);
12	  });
13	  it.todo("should charge 60G base premium plus fee for a single amulet");
14	  it.todo("should charge 80G base premium plus fee for a single staff");
15	  it.todo("should charge 40G base premium plus fee for a single potion");
16	  it.todo("should charge 25G base premium plus fee for a single rune");
17	  it.todo("should charge 25G base premium plus fee for a single moonstone");
18	  it.todo("should sum the base premiums of several different main items");
19	});
20	
21	describe("Claim Office - quote: component blocks", () => {
22	  it.todo("should charge 50G base premium for 2 runes (no block)");
23	  it.todo("should charge 60G base premium for exactly 3 runes (block applies)");
24	  it.todo("should charge 100G base premium for 4 runes (no block for the remainder)");
