31	  it.todo("should add a 50% surcharge on a cursed item's base premium");
32	  it.todo("should add a 30% surcharge for an item with enchantment exactly 5");
33	  it.todo("should not add the high-enchantment surcharge for an item with enchantment 4");
34	  it.todo("should add both surcharges for an item that is cursed and enchantment >= 5");
35	  it.todo("should apply the cursed surcharge only to the cursed item's base premium, not the policy total");
