47	describe("Claim Office - quote: rounding", () => {
48	  it.todo("should round the final premium up to a whole G");
49	});
50	
51	describe("Claim Office - quote: integration", () => {
52	  it.todo("should charge 165G for a newcomer's cursed steel sword with enchantment 3");
53	  it.todo("should charge 160G for a 3-year customer's second contract with a cursed sword of enchantment 7");
54	});
55	
56	describe("Claim Office - quote: errors", () => {
57	  it.todo("should reject a quote containing an item with an unknown type");
58	});
59	
60	describe("Claim Office - claim: insurance sum and cap", () => {
61	  it.todo("should cap the policy payout at twice the insurance sum of a single sword");
62	  it.todo("should sum the insurance values of several items to derive the cap");
63	  it.todo("should base the cap on unmodified insurance values, ignoring premium modifiers");
64	  it.todo("should base the cap on the full component insurance values, ignoring the block discount");
