68	  it.todo("should pay the damage amount minus the 100G deductible for a regular sword");
69	  it.todo("should pay the damage amount minus the 100G deductible for a damaged rune");
70	  it.todo("should apply the 100G deductible once per damage entry when several items are damaged");
