72	
73	describe("Claim Office - claim: special clauses", () => {
74	  it.todo("should reimburse 50% of the damage before the deductible for enchantment exactly 8");
75	  it.todo("should reimburse dragon material fully before the deductible");
76	  it.todo("should let the 50% enchantment rule win when both the enchantment and dragon clauses apply");
77	  it.todo("should reimburse a dragon-material item with enchantment below 8 in full before the deductible");
