84	
85	describe("Claim Office - claim: rounding", () => {
86	  it.todo("should round the final payout down to a whole G");
87	});
88	
89	describe("Claim Office - claim: multiple items of the same type", () => {
90	  it.todo("should treat two damage entries of the same item type as separate damages with their own deductibles");
