1	export type Customer = {
2	  yearsWithMHPCO: number;
3	  previousContracts: number;
4	};
5	
6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	const SWORD_BASE_PREMIUM = 100;
15	
16	export const quote = (customer: Customer, items: Item[]): number => {
17	  return items.length * SWORD_BASE_PREMIUM + PROCESSING_FEE;
18	};
19	
20	export const claim = (): number => {
21	  return undefined as unknown as number;
22	};
